/// 删除书籍及其缓存、搜索索引和封面文件
#[frb]
pub async fn delete_book(book_id: String, covers_dir: String) -> Result<(), AppError> {
    tracing::info!("[book] delete_book: book_id={}", book_id);
    service::delete_book(&book_id, &covers_dir).await?;
    // 搜索索引清理由 API 层负责（避免 service → api 循环依赖）
