/// 级联删除书籍（含封面文件删除、缓存失效）
///
/// 注意：搜索索引清理由调用方负责（search::delete_by_book）
pub async fn delete_book(book_id: &str, covers_dir: &str) -> Result<(), AppError> {
    let pool = storage_pool()?;

    // 先查 file_path（级联删除后 book 行消失）
    let file_path = match BookRepository::find_by_id(&pool, book_id).await {
        Ok(Some(book)) => Some(book.file_path),
        _ => None,
    };

    // 删除封面文件
    if let Ok(Some(cover_path)) = BookRepository::find_cover_path(&pool, book_id).await {
        let full_path = std::path::Path::new(covers_dir).join(&cover_path);
        if full_path.exists()
            && let Err(e) = tokio::fs::remove_file(&full_path).await {
                tracing::warn!("[book] failed to delete cover file: {}", e);
            }
    }

    // 级联删除关联数据
    BookRepository::delete_cascade(&pool, book_id)
        .await
        .map_err(|e| AppError::DatabaseError { reason: e.to_string() })?;

    // 失效 IR 缓存
    if let Some(ref fp) = file_path {
        let kv = crate::infra::ensure_storage()?.kv();
        let cache_repo = IrCacheRepository::new(kv);
        if let Err(e) = cache_repo.invalidate_book_cache(fp) {
            tracing::warn!("[book] failed to clear ir cache for '{}': {}", fp, e);
        }
    } else {
        tracing::warn!("[book] book '{}' not found — cannot invalidate IR cache", book_id);
    }

    Ok(())
}

/// 创建外部导入的书籍（如来自网页搜索）
pub async fn create_web_book(
    title: &str,
    author: &str,
    file_path: &str,
    chapter_count: i64,
    total_characters: i64,
    cover_path: Option<&str>,
    description: Option<&str>,
) -> Result<Book, AppError> {
    let book = Book::new(
        file_path.to_string(), 0, title.to_string(), BookFormat::Txt, chapter_count, total_characters,
        None, None, Some(author.to_string()), cover_path.map(|s| s.to_string()), description.map(|s| s.to_string()), None, None, None,
    );
    let pool = storage_pool()?;
    BookRepository::save(&pool, &book).await?;
    BookRepository::save_metadata(&pool, &book).await?;
    Ok(book)
}

/// 批量更新书籍阅读状态
pub async fn batch_update_book_status(book_ids: &[String], status: BookStatus) -> Result<(), AppError> {
    let pool = storage_pool()?;
    let mut tx = pool.begin().await?;
    for book_id in book_ids {
        sqlx::query("UPDATE books SET status = ? WHERE id = ?")
            .bind(status.as_ref())
            .bind(book_id)
            .execute(&mut *tx)
            .await?;
    }
    tx.commit().await?;
    Ok(())
}

/// 批量设置书籍分类
pub async fn batch_set_categories_for_books(
    book_ids: &[String],
    category_ids: &[String],
) -> Result<(), AppError> {
    let pool = storage_pool()?;
    let mut tx = pool.begin().await?;
    for book_id in book_ids {
        sqlx::query("DELETE FROM book_categories WHERE book_id = ?")
            .bind(book_id)
            .execute(&mut *tx)
            .await?;
        for cat_id in category_ids {
            sqlx::query(
                "INSERT INTO book_categories (book_id, category_id) VALUES (?, ?) \
                 ON CONFLICT(book_id, category_id) DO NOTHING",
            )
            .bind(book_id)
            .bind(cat_id)
            .execute(&mut *tx)
            .await?;
        }
    }
    tx.commit().await?;
    Ok(())
}

/// 解析书籍文件
///
/// 导入书籍：验证路径、检查大小限制、选择解析器、保存元数据。
pub async fn import_book(file_path: &str) -> Result<String, AppError> {
    const MAX_FILE_SIZE: u64 = 500 * 1024 * 1024;

    let validated_path = validate_file_path(file_path)?;
    let metadata = tokio::fs::metadata(&validated_path).await
        .map_err(|e| AppError::FileReadError { path: validated_path.clone(), details: e.to_string() })?;
    if metadata.len() > MAX_FILE_SIZE {
        return Err(AppError::SecurityError {
            reason: format!("file size exceeds limit (max {} MB)", MAX_FILE_SIZE / 1024 / 1024),
            path: validated_path,
        });
    }

    let pool = storage_pool()?;
    if let Some(existing) = BookRepository::find_by_file_path(&pool, &validated_path).await? {
        return Ok(existing.book_id);
    }

    let parser = parser_for_file(&validated_path)?;
    let result = parser.parse(&validated_path).await?;
    BookRepository::save(&pool, &result.book_info).await?;
    BookRepository::save_metadata(&pool, &result.book_info).await?;
    ChapterRepository::save(&pool, &result.book_info.book_id, &result.chapters).await?;
    Ok(result.book_info.book_id)
}

//! 封面管理业务逻辑
//!
//! 提供封面提取、数据库保存和格式检测功能。
//! 封面提取委托给 engine，数据访问委托给 BookRepository。

use std::path::Path;

use crate::common::AppError;
use crate::common::security::validate_file_path;
use crate::domain::book::book_repo::BookRepository;
use crate::domain::cover::engine::get_cover_registry;
use crate::infra::manager::storage_pool;

/// 提取书籍封面
pub async fn extract_book_cover(file_path: &str, output_dir: &str) -> Result<String, AppError> {
    let validated_path = validate_file_path(file_path)?;
    let registry = get_cover_registry();
    registry.extract_cover(&validated_path, output_dir)
}

/// 提取书籍封面并保存路径到数据库
///
/// 如果数据库保存失败，自动清理已提取的封面文件。
pub async fn extract_and_save_cover(
    book_id: &str,
    file_path: &str,
    output_dir: &str,
) -> Result<String, AppError> {
    let full_path = extract_book_cover(file_path, output_dir).await?;

    let relative_path = Path::new(&full_path)
        .file_name()
        .and_then(|n| n.to_str())
        .unwrap_or("")
        .to_string();

    if relative_path.is_empty() {
        // 清理孤立封面文件
        let _ = tokio::fs::remove_file(&full_path).await;
        return Err(AppError::Other("failed to extract cover filename".into()));
    }

    let pool = storage_pool()?;
    if let Err(e) = BookRepository::update_cover_path(&pool, book_id, &relative_path).await {
        // 数据库写入失败，清理封面文件
        if let Err(cleanup_err) = tokio::fs::remove_file(&full_path).await {
            tracing::warn!(
                "cover file cleanup failed after DB error: {} (cleanup: {})",
                e,
                cleanup_err
            );
        }
        return Err(AppError::DatabaseError {
            reason: e.to_string(),
        });
    }
    Ok(relative_path)
}

/// 检查是否支持封面提取（同步，无需 DB）
pub fn supports_cover_extraction(file_path: &str) -> bool {
    let path = Path::new(file_path);
    let extension = path
        .extension()
        .and_then(|e| e.to_str())
        .map(|s| s.to_lowercase())
        .unwrap_or_default();
    let registry = get_cover_registry();
    registry.supports_format(&extension)
}

//! 词典业务逻辑
//!
//! 引擎操作委托给 Engine，数据访问委托给 DictionaryRepository。
//! 纯 CRUD 透传已内联到 api/ 层，此处只保留有实际业务逻辑的操作。

use std::sync::LazyLock;

